import { test, expect } from '@playwright/test';

test.describe('Accessible Product Images and Login Fields', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should have accessible attributes for product images and login fields', async ({ page }) => {
    // Verify login fields have accessible attributes
    const usernameField = page.getByLabel('Username');
    await expect(usernameField).toBeVisible();
    await expect(usernameField).toHaveAttribute('placeholder', 'Enter username');

    const passwordField = page.getByLabel('Password');
    await expect(passwordField).toBeVisible();
    await expect(passwordField).toHaveAttribute('placeholder', 'Enter password');

    // Verify login button is accessible
    const loginButton = page.getByRole('button', { name: /log in/i });
    await expect(loginButton).toBeVisible();

    // Verify login form is accessible
    const loginForm = page.locator('[data-testid="login-form"]');
    await expect(loginForm).toBeVisible();

    // Verify product images have accessible alt attributes
    const productItems = page.locator('[data-testid="inventory-item"]');
    await expect(productItems).toHaveCount(3);

    const firstProductImage = page.locator('[data-testid="inventory-item-img"]');
    await expect(firstProductImage).toBeVisible();
    await expect(firstProductImage).toHaveAttribute('alt', 'Product 1 description');

    const secondProductImage = page.locator('[data-testid="inventory-item-img"]');
    await expect(secondProductImage).toBeVisible();
    await expect(secondProductImage).toHaveAttribute('alt', 'Product 2 description');

    const thirdProductImage = page.locator('[data-testid="inventory-item-img"]');
    await expect(thirdProductImage).toBeVisible();
    await expect(thirdProductImage).toHaveAttribute('alt', 'Product 3 description');

    // Verify login with standard_user
    await usernameField.fill('standard_user');
    await passwordField.fill('secret_sauce');
    await loginButton.click();

    // Verify successful login message is visible
    const successMessage = page.getByText('Login successful');
    await expect(successMessage).toBeVisible();

    // Verify product images still have accessible alt attributes after login
    await expect(firstProductImage).toHaveAttribute('alt', 'Product 1 description');
    await expect(secondProductImage).toHaveAttribute('alt', 'Product 2 description');
    await expect(thirdProductImage).toHaveAttribute('alt', 'Product 3 description');
  });

  test('should handle login failure and maintain accessible product images', async ({ page }) => {
    // Verify login form is visible
    const loginForm = page.locator('[data-testid="login-form"]');
    await expect(loginForm).toBeVisible();

    // Verify login button is accessible
    const loginButton = page.getByRole('button', { name: /log in/i });
    await expect(loginButton).toBeVisible();

    // Verify login form is accessible
    await expect(loginForm).toBeVisible();

    // Verify product images have accessible alt attributes
    const productItems = page.locator('[data-testid="inventory-item"]');
    await expect(productItems).toHaveCount(3);

    const firstProductImage = page.locator('[data-testid="inventory-item-img"]');
    await expect(firstProductImage).toBeVisible();
    await expect(firstProductImage).toHaveAttribute('alt', 'Product 1 description');

    const secondProductImage = page.locator('[data-testid="inventory-item-img"]');
    await expect(secondProductImage).toBeVisible();
    await expect(secondProductImage).toHaveAttribute('alt', 'Product 2 description');

    const thirdProductImage = page.locator('[data-testid="inventory-item-img"]');
    await expect(thirdProductImage).toBeVisible();
    await expect(thirdProductImage).toHaveAttribute('alt', 'Product 3 description');

    // Attempt to login with invalid credentials
    await usernameField.fill('invalid_user');
    await passwordField.fill('wrong_password');
    await loginButton.click();

    // Verify login error message is visible
    const errorMessage = page.getByText('Invalid credentials');
    await expect(errorMessage).toBeVisible();

    // Verify product images still have accessible alt attributes after login failure
    await expect(firstProductImage).toHaveAttribute('alt', 'Product 1 description');
    await expect(secondProductImage).toHaveAttribute('alt', 'Product 2 description');
    await expect(thirdProductImage).toHaveAttribute('alt', 'Product 3 description');
  });
});
